const weekday = '(?:Mon|Tue|Wed|Thu|Fri|Sat|Sun)';
const month = '(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)';
const time = '(?:[01]\\d|2[0-3]):[0-5]\\d:[0-5]\\d';
const datePatterns = [
  new RegExp(`^${weekday}, (\\d{2}) ${month} \\d{4} ${time} GMT$`, 'i'),
  new RegExp(`^(?:Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday), (\\d{2})-${month}-\\d{2} ${time} GMT$`, 'i'),
  new RegExp(`^${weekday} ${month} ( [1-9]|\\d{2}) ${time} \\d{4}$`, 'i'),
];

function httpDate(value) {
  for (const [index, pattern] of datePatterns.entries()) {
    const match = pattern.exec(value);
    if (!match) continue;
    // asctime has no zone marker, but HTTP dates always use UTC.
    const timestamp = Date.parse(index === 2 ? `${value} GMT` : value);
    const day = Number(match[index === 2 ? 2 : 1]);
    if (Number.isFinite(timestamp) && new Date(timestamp).getUTCDate() === day) {
      return timestamp;
    }
  }
  return NaN;
}

export function retryDelay(headers, index, base, now = Date.now) {
  const entry = Object.entries(headers ?? {}).find(([name]) =>
    name.toLowerCase() === 'retry-after');
  const value = typeof entry?.[1] === 'string' ? entry[1].trim() : '';
