    return Math.min(2000, Number(value) * 1000);
  }
  const timestamp = httpDate(value);
  if (Number.isFinite(timestamp)) {
    return Math.min(2000, Math.max(0, timestamp - now()));
  }
  return Math.min(2000, base * 2 ** index);
