import assert from 'node:assert/strict';
import {test} from 'node:test';
import {requestWithRetry} from './src/retry.mjs';
import {retryDelay} from './src/delay.mjs';

const epoch = Date.UTC(2026, 8, 24, 12);

function harness(responses, options = {}) {
  const requests = [];
  const delays = [];
  let time = epoch;
  return {
    requests, delays,
    run(request) {
      return requestWithRetry(input => {
        requests.push(input);
        assert.ok(requests.length <= responses.length, 'unexpected extra attempt');
        return responses[requests.length - 1];
      }, request, {
        now: () => time,
        sleep: async ms => { delays.push(ms); time += ms; },
        ...options,
      });
    },
  };
}

test('preserves request and final response identity; defaults to three attempts', async () => {
  const request = Object.freeze({method: 'gEt', headers: Object.freeze({}), body: 'body'});
  const final = Object.freeze({status: 503, headers: Object.freeze({})});
  const h = harness([{status: 429}, {status: 503}, final]);
  const pending = h.run(request);
  assert.ok(pending instanceof Promise);
  assert.equal(await pending, final);
  assert.deepEqual(h.delays, [100, 200]);
  assert.equal(h.requests.length, 3);
  h.requests.forEach(actual => assert.equal(actual, request));
  assert.deepEqual(request, {method: 'gEt', headers: {}, body: 'body'});
});

test('retries only eligible methods or nonempty case-insensitive idempotency keys', async () => {
  for (const request of [
    {method: 'GET'}, {method: 'hEaD'},
    {method: 'POST', headers: {'iDeMpOtEnCy-KeY': ' key '}},
    {method: 'PATCH', headers: {'IDEMPOTENCY-KEY': '0'}},
  ]) {
    const h = harness([{status: 503}, {status: 200}]);
    assert.equal((await h.run(request)).status, 200);
    assert.deepEqual(h.delays, [100]);
  }
  for (const request of [
    {}, {method: 'POST'}, {method: 'PUT'}, {method: 'DELETE'},
    {method: 'POST', headers: {'Idempotency-Key': ''}},
    {method: 'POST', headers: {'idempotency-key': ' \t '}},
    {method: 'POST', headers: {'Other-Key': 'key'}},
  ]) {
    const final = {status: 429};
    const h = harness([final]);
    assert.equal(await h.run(request), final);
    assert.deepEqual(h.delays, []);
  }
});

test('all statuses other than 429 and 503 return immediately', async () => {
  for (const status of [200, 204, 301, 400, 401, 404, 408, 500, 502, 504]) {
    const final = {status};
    const h = harness([final]);
    assert.equal(await h.run({method: 'GET'}), final);
    assert.deepEqual(h.delays, []);
  }
});

test('attempt limits 1 through 5 and zero base delay', async () => {
  for (let maxAttempts = 1; maxAttempts <= 5; maxAttempts++) {
    const responses = Array.from({length: maxAttempts}, () => ({status: 503}));
    const h = harness(responses, {maxAttempts, baseDelayMs: 0});
    assert.equal(await h.run({method: 'GET'}), responses.at(-1));
    assert.equal(h.requests.length, maxAttempts);
    assert.deepEqual(h.delays, Array(maxAttempts - 1).fill(0));
  }
});

test('invalid options reject as Promises before transport is called', async () => {
  for (const [name, values] of [
    ['maxAttempts', [0, -1, 6, 1.5, NaN, Infinity, '3', null, true]],
    ['baseDelayMs', [-1, NaN, Infinity, -Infinity, '100', null, true]],
  ]) {
    for (const value of values) {
      let calls = 0;
      const promise = requestWithRetry(() => { calls++; }, {method: 'GET'}, {[name]: value});
      assert.ok(promise instanceof Promise);
      await assert.rejects(promise, RangeError);
      assert.equal(calls, 0);
    }
  }
});

test('synchronous throws and rejected errors propagate unchanged without retry', async () => {
  for (const asynchronous of [false, true]) {
    for (const failAt of [1, 2]) {
      const error = {reason: 'transport failure'};
      let calls = 0;
      const delays = [];
      const promise = requestWithRetry(() => {
        if (++calls < failAt) return {status: 503};
        if (asynchronous) return Promise.reject(error);
        throw error;
      }, {method: 'GET'}, {sleep: async ms => delays.push(ms), now: () => epoch});
      await assert.rejects(promise, actual => actual === error);
      assert.equal(calls, failAt);
      assert.equal(delays.length, failAt - 1);
    }
  }
});

test('Retry-After seconds, HTTP dates, bounds, invalid values and fallback', () => {
  const cases = [
    ['0', 0], ['1', 1000], ['0001', 1000], [' 1 ', 1000], ['2', 2000],
    ['999999999999999999999999', 2000],
    [new Date(epoch + 1000).toUTCString(), 1000],
    [new Date(epoch + 60000).toUTCString(), 2000],
    [new Date(epoch - 1000).toUTCString(), 0],
    ['Thursday, 24-Sep-26 12:00:01 GMT', 1000],
    ['Thu Sep 24 12:00:01 2026', 1000],
    ['', 150], ['nonsense', 150], ['-1', 150], ['1.5', 150], ['+1', 150],
    ['1e3', 150], ['2026-09-24T12:00:01Z', 150], ['12/25/2026', 150],
    ['Mon, 30 Feb 2026 12:00:01 GMT', 150],
    ['Thu, 24 Sep 2026 25:00:00 GMT', 150],
  ];
  for (const [value, expected] of cases) {
    assert.equal(retryDelay({'rEtRy-AfTeR': value}, 1, 75, () => epoch), expected, value);
  }
  assert.equal(retryDelay(undefined, 0, 0, () => epoch), 0);
  assert.equal(retryDelay({}, 0, 0.5, () => epoch), 0.5);
  assert.equal(retryDelay({}, 4, 500, () => epoch), 2000);
  assert.equal(retryDelay({}, 4, Number.MAX_VALUE, () => epoch), 2000);
});

test('clock advances during injected sleeps and each response controls its next delay', async () => {
  const future = new Date(epoch + 2000).toUTCString();
  const final = {status: 200};
  const h = harness([
    {status: 429, headers: {'Retry-After': '1'}},
    {status: 503, headers: {'retry-after': future}},
    {status: 503, headers: {'Retry-After': 'invalid'}},
    {status: 503}, final,
  ], {maxAttempts: 5, baseDelayMs: 400});
  assert.equal(await h.run({method: 'HEAD'}), final);
  assert.deepEqual(h.delays, [1000, 1000, 1600, 2000]);
});

test('awaits sleep before sending another request', async () => {
  let release;
  let calls = 0;
  const pending = requestWithRetry(async () => ({status: ++calls === 1 ? 503 : 200}),
    {method: 'GET'}, {
      sleep: () => new Promise(resolve => { release = resolve; }),
      now: () => epoch,
    });
  await Promise.resolve();
  assert.equal(calls, 1);
  assert.equal(typeof release, 'function');
  release();
  assert.equal((await pending).status, 200);
  assert.equal(calls, 2);
});

