import {retryDelay} from './delay.mjs';

const defaultSleep = ms => new Promise(resolve => setTimeout(resolve, ms));

export async function requestWithRetry(send, request, options = {}) {
  const {
    maxAttempts = 3,
    baseDelayMs = 100,
    sleep = defaultSleep,
    now = Date.now,
  } = options;

  if (!Number.isInteger(maxAttempts) || maxAttempts < 1 || maxAttempts > 5) {
    throw new RangeError('maxAttempts must be an integer from 1 to 5');
  }
  if (typeof baseDelayMs !== 'number' || !Number.isFinite(baseDelayMs) || baseDelayMs < 0) {
    throw new RangeError('baseDelayMs must be a finite nonnegative number');
  }

  const method = String(request.method ?? '').toUpperCase();
  const canRetry = method === 'GET' || method === 'HEAD' ||
    Object.entries(request.headers ?? {}).some(([name, value]) =>
      name.toLowerCase() === 'idempotency-key' &&
      typeof value === 'string' && value.trim().length > 0);

  for (let attempt = 0; attempt < maxAttempts; attempt++) {
    const response = await send(request);
    if (!canRetry || (response.status !== 429 && response.status !== 503) ||
        attempt === maxAttempts - 1) {
      return response;
    }
    await sleep(retryDelay(response.headers, attempt, baseDelayMs, now));
  }
}

