    'Sun, 30 Feb 2025 08:49:38 GMT', 'Sun, 06 Nov 1994 25:49:38 GMT']) {
    const f = fixture([{status: 429, headers: {'Retry-After': value}}]);
    await f.promise;
    assert.deepEqual(f.delays, [100, 200], String(value));
  }
});

test('thrown and rejected transport errors propagate unchanged without retry', async () => {
