import assert from 'node:assert/strict';
import test from 'node:test';
import {requestWithRetry} from '../src/retry.mjs';

const epoch = Date.parse('Sun, 06 Nov 1994 08:49:37 GMT');
function fixture(responses, request = {method: 'GET'}, options = {}) {
  const calls = [];
  const delays = [];
  let time = epoch;
  const promise = requestWithRetry(req => {
    calls.push(req);
    return responses[Math.min(calls.length - 1, responses.length - 1)];
  }, request, {
    now: () => time,
    sleep: async ms => { delays.push(ms); time += ms; },
    ...options,
  });
  assert.ok(promise instanceof Promise);
  return {promise, calls, delays};
}

test('defaults, exponential delays, original request and final response identity', async () => {
  const request = Object.freeze({method: 'GET', headers: Object.freeze({foo: 'bar'})});
  const final = Object.freeze({status: 503});
  const f = fixture([{status: 429}, {status: 503}, final], request);
  assert.strictEqual(await f.promise, final);
  assert.deepEqual(f.delays, [100, 200]);
  assert.equal(f.calls.length, 3);
  for (const call of f.calls) assert.strictEqual(call, request);
});

test('only eligible methods or nonempty case-insensitive keys retry', async () => {
  for (const [request, expected] of [
    [{method: 'get'}, 3], [{method: 'HeAd'}, 3],
    [{method: 'POST', headers: {'iDeMpOtEnCy-KeY': ' token '}}, 3],
    [{method: 'PATCH', headers: {'IDEMPOTENCY-KEY': 'x'}}, 3],
    [{method: 'POST'}, 1], [{method: 'PUT'}, 1], [{method: 'DELETE'}, 1],
    [{method: 'OPTIONS'}, 1], [{}, 1],
    [{method: 'POST', headers: {'Idempotency-Key': ''}}, 1],
    [{method: 'POST', headers: {'Idempotency-Key': ' \t\n'}}, 1],
    [{method: 'POST', headers: {'Idempotency-Key': null}}, 1],
  ]) {
    const f = fixture([{status: 503}], request);
    await f.promise;
    assert.equal(f.calls.length, expected, JSON.stringify(request));
    assert.equal(f.delays.length, expected - 1);
  }
});

test('only 429 and 503 retry; other statuses stop immediately', async () => {
  for (const status of [200, 204, 301, 400, 401, 404, 408, 500, 502, 504]) {
    const response = {status};
    const f = fixture([response]);
    assert.strictEqual(await f.promise, response);
    assert.equal(f.calls.length, 1);
    assert.deepEqual(f.delays, []);
  }
  const response = {status: 200};
  const f = fixture([{status: 503}, response]);
  assert.strictEqual(await f.promise, response);
  assert.equal(f.calls.length, 2);
  assert.deepEqual(f.delays, [100]);
});

test('attempt limits include first attempt and never sleep after final response', async () => {
  for (const maxAttempts of [1, 2, 3, 4, 5]) {
    const f = fixture([{status: 429}], {method: 'GET'}, {maxAttempts, baseDelayMs: 600});
    await f.promise;
    assert.equal(f.calls.length, maxAttempts);
    assert.deepEqual(f.delays, [600, 1200, 2000, 2000].slice(0, maxAttempts - 1));
  }
});

test('invalid options reject as Promises before transport runs', async () => {
  for (const [name, values] of [
    ['maxAttempts', [0, -1, 6, 1.5, NaN, Infinity, '3', null, true]],
    ['baseDelayMs', [-1, NaN, Infinity, -Infinity, '100', null, true]],
  ]) {
    for (const value of values) {
      const f = fixture([{status: 200}], {method: 'GET'}, {[name]: value});
      await assert.rejects(f.promise, RangeError);
      assert.deepEqual(f.calls, []);
      assert.deepEqual(f.delays, []);
    }
  }
});

test('zero, fractional, and large finite base delays are respected', async () => {
  for (const [baseDelayMs, expected] of [[0, [0, 0]], [0.5, [0.5, 1]], [Number.MAX_VALUE, [2000, 2000]]]) {
    const f = fixture([{status: 429}], {method: 'GET'}, {baseDelayMs});
    await f.promise;
    assert.deepEqual(f.delays, expected);
  }
});

test('Retry-After seconds use case-insensitive names and override base delay', async () => {
  for (const [value, expected] of [['0', 0], ['1', 1000], ['002', 2000], ['99', 2000], ['9'.repeat(400), 2000], [' 1 ', 1000]]) {
    const f = fixture([{status: 503, headers: {'rEtRy-AfTeR': value}}], {method: 'GET'}, {maxAttempts: 2});
    await f.promise;
    assert.deepEqual(f.delays, [expected]);
  }
});

test('HTTP dates use injected current time, floor past dates and cap future dates', async () => {
  for (const [value, expected] of [
    ['Sun, 06 Nov 1994 08:49:38 GMT', [1000, 0]],
    ['Sun, 06 Nov 1994 08:49:36 GMT', [0, 0]],
    ['Sun, 06 Nov 1994 08:50:37 GMT', [2000, 2000]],
    ['Sunday, 06-Nov-94 08:49:38 GMT', [1000, 0]],
    ['Sun Nov  6 08:49:38 1994', [1000, 0]],
  ]) {
    const f = fixture([{status: 503, headers: {'retry-after': value}}]);
    await f.promise;
    assert.deepEqual(f.delays, expected, value);
  }
});

test('missing or invalid Retry-After uses exponential fallback', async () => {
  for (const value of [undefined, null, '', 'garbage', '-1', '+1', '1.5', '1e3', 'Infinity', '2026-09-24',
    'Sun, 30 Feb 2025 08:49:38 GMT', 'Sun, 06 Nov 1994 25:49:38 GMT']) {
    const f = fixture([{status: 429, headers: {'Retry-After': value}}]);
    await f.promise;
    assert.deepEqual(f.delays, [100, 200], String(value));
  }
});

test('thrown and rejected transport errors propagate unchanged without retry', async () => {
  for (const error of [new Error('transport failed'), {reason: 'failure'}, 'failure']) {
    for (const asyncError of [false, true]) {
      let calls = 0;
      const promise = requestWithRetry(() => {
        calls++;
        if (asyncError) return Promise.reject(error);
        throw error;
      }, {method: 'GET'}, {sleep: async () => assert.fail('must not sleep'), now: () => epoch});
      assert.ok(promise instanceof Promise);
      await assert.rejects(promise, actual => actual === error);
      assert.equal(calls, 1);
    }
  }
});

test('transport error after an earlier retry also propagates unchanged', async () => {
  const error = new Error('second attempt failed');
  let calls = 0;
  const delays = [];
  await assert.rejects(requestWithRetry(() => {
    if (++calls === 1) return {status: 503};
    throw error;
  }, {method: 'GET'}, {sleep: async ms => delays.push(ms), now: () => epoch}), actual => actual === error);
  assert.equal(calls, 2);
  assert.deepEqual(delays, [100]);
});

test('retry waits for injected sleep to finish', async () => {
  let release;
  let calls = 0;
  const promise = requestWithRetry(() => ({status: ++calls === 1 ? 503 : 200}), {method: 'GET'}, {
    sleep: () => new Promise(resolve => { release = resolve; }), now: () => epoch,
  });
  await Promise.resolve();
  assert.equal(calls, 1);
  release();
  assert.equal((await promise).status, 200);
  assert.equal(calls, 2);
});

