+function parseHttpDate(value) {
+  let match = httpDatePatterns.map(pattern => pattern.exec(value)).find(Boolean);
+  const old = asctime.exec(value);
+  if (!match && old) {
+    match = [old[0], old[1], old[3], old[2], old[7], old[4], old[5], old[6]];
