+  const timestamp = Date.parse(old ? `${value} GMT` : value);
+  const date = new Date(timestamp);
+  // Reject impossible dates that Date.parse silently normalizes.
+  if (date.getUTCDate() !== Number(day) || date.getUTCMonth() !== months.indexOf(month) ||
+      date.getUTCHours() !== Number(hour) || date.getUTCMinutes() !== Number(minute) ||
+      date.getUTCSeconds() !== Number(second) ||
+      (year.length === 4 && date.getUTCFullYear() !== Number(year)) ||
+      date.toUTCString().slice(0, 3) !== weekday.slice(0, 3)) return NaN;
+  return timestamp;
+}
