// HTTP dates allow IMF-fixdate and the two obsolete wire formats. Do not
// accept Date.parse's additional inputs (e.g. signed numbers or ISO dates).
const httpDatePatterns = [
  /^(Mon|Tue|Wed|Thu|Fri|Sat|Sun), (\d{2}) (Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec) (\d{4}) (\d{2}):(\d{2}):(\d{2}) GMT$/,
  /^(Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday), (\d{2})-(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)-(\d{2}) (\d{2}):(\d{2}):(\d{2}) GMT$/,
];
const asctime = /^(Mon|Tue|Wed|Thu|Fri|Sat|Sun) (Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec) ( [1-9]|\d{2}) (\d{2}):(\d{2}):(\d{2}) (\d{4})$/;
const months = 'Jan Feb Mar Apr May Jun Jul Aug Sep Oct Nov Dec'.split(' ');

function parseHttpDate(value) {
  let match = httpDatePatterns.map(pattern => pattern.exec(value)).find(Boolean);
  const old = asctime.exec(value);
  if (!match && old) {
    match = [old[0], old[1], old[3], old[2], old[7], old[4], old[5], old[6]];
  }
  if (!match) return NaN;
  const [, weekday, day, month, year, hour, minute, second] = match;
  const timestamp = Date.parse(old ? `${value} GMT` : value);
  const date = new Date(timestamp);
  // Reject impossible dates that Date.parse silently normalizes.
  if (date.getUTCDate() !== Number(day) || date.getUTCMonth() !== months.indexOf(month) ||
      date.getUTCHours() !== Number(hour) || date.getUTCMinutes() !== Number(minute) ||
      date.getUTCSeconds() !== Number(second) ||
      (year.length === 4 && date.getUTCFullYear() !== Number(year)) ||
      date.toUTCString().slice(0, 3) !== weekday.slice(0, 3)) return NaN;
  return timestamp;
}

export function retryDelay(headers, index, base, now = Date.now) {
  const entry = Object.entries(headers ?? {}).find(([name]) => name.toLowerCase() === 'retry-after');
  const value = typeof entry?.[1] === 'string' ? entry[1].trim() : '';
  if (/^\d+$/.test(value)) return Math.min(2000, Number(value) * 1000);
  const timestamp = parseHttpDate(value);
  if (Number.isFinite(timestamp)) return Math.min(2000, Math.max(0, timestamp - now()));
