const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
  'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

function httpDate(value) {
  // HTTP accepts IMF-fixdate and the two obsolete HTTP-date formats.
  const standard = /^(?:Mon|Tue|Wed|Thu|Fri|Sat|Sun), (\d{2}) ([A-Z][a-z]{2}) (\d{4}) (\d{2}):(\d{2}):(\d{2}) GMT$/;
  const obsolete = /^(?:Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday), (\d{2})-([A-Z][a-z]{2})-(\d{2}) (\d{2}):(\d{2}):(\d{2}) GMT$/;
  const asctime = /^(?:Mon|Tue|Wed|Thu|Fri|Sat|Sun) ([A-Z][a-z]{2}) ([ \d]\d) (\d{2}):(\d{2}):(\d{2}) (\d{4})$/;
  let parts = standard.exec(value) ?? obsolete.exec(value);
  if (!parts) {
    const match = asctime.exec(value);
    if (match) parts = [match[0], match[2], match[1], match[6], match[3], match[4], match[5]];
  }
  if (!parts) return NaN;
  // Explicit GMT keeps the timezone-less asctime form independent of local time.
  const timestamp = Date.parse(value.endsWith('GMT') ? value : `${value} GMT`);
  const date = new Date(timestamp);
  if (date.getUTCDate() !== Number(parts[1]) ||
      date.getUTCMonth() !== months.indexOf(parts[2]) ||
      date.getUTCHours() !== Number(parts[4]) ||
      date.getUTCMinutes() !== Number(parts[5]) ||
      date.getUTCSeconds() !== Number(parts[6])) return NaN;
  return timestamp;
}

export function retryDelay(headers, index, base, now = Date.now) {
  const entry = Object.entries(headers ?? {}).find(([name]) =>
    name.toLowerCase() === 'retry-after');
  const value = typeof entry?.[1] === 'string' ? entry[1].trim() : '';
  if (/^\d+$/.test(value)) return Math.min(2000, Number(value) * 1000);
  const timestamp = httpDate(value);
  if (Number.isFinite(timestamp)) return Math.min(2000, Math.max(0, timestamp - now()));
  return Math.min(2000, base * 2 ** index);
}

